public enum PullRequestViewedFilesStore: Sendable, Hashable, Codable, RawRepresentable {
  case host
  case environment
  /// A value this build does not know; kept verbatim so it round-trips.
  case unknown(String)

  public init(rawValue: String) {
    switch rawValue {
    case "host": self = .host
    case "environment": self = .environment
    default: self = .unknown(rawValue)
    }
  }

  public var rawValue: String {
    switch self {
    case .host: "host"
    case .environment: "environment"
    case .unknown(let value): value
    }
  }

  public init(from decoder: any Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: any Encoder) throws {
    var c = encoder.singleValueContainer()
    try c.encode(rawValue)
  }
}

public struct PullRequestViewerPermissions: Sendable, Hashable, Codable {
  public var stackRebase: Bool?
  public var actions: [PullRequestAction]
  public var comment: Bool
  public var resolve: Bool
  public var verdicts: [PullRequestReviewVerdict]
  public var requestReviewers: Bool
  public var updateMethods: [PullRequestUpdateMethod]?
  public var labels: Bool?

  public init(stackRebase: Bool? = nil, actions: [PullRequestAction], comment: Bool, resolve: Bool, verdicts: [PullRequestReviewVerdict], requestReviewers: Bool, updateMethods: [PullRequestUpdateMethod]? = nil, labels: Bool? = nil) {
    self.stackRebase = stackRebase
    self.actions = actions
    self.comment = comment
    self.resolve = resolve
    self.verdicts = verdicts
    self.requestReviewers = requestReviewers
    self.updateMethods = updateMethods
    self.labels = labels
  }

  private enum CodingKeys: String, CodingKey {
    case stackRebase
    case actions
    case comment
    case resolve
    case verdicts
    case requestReviewers
    case updateMethods
    case labels
  }

  public init(from decoder: any Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    self.stackRebase = try c.decodeIfPresent(Bool.self, forKey: .stackRebase)
    self.actions = try c.decode([PullRequestAction].self, forKey: .actions)
    self.comment = try c.decode(Bool.self, forKey: .comment)
    self.resolve = try c.decode(Bool.self, forKey: .resolve)
    self.verdicts = try c.decode([PullRequestReviewVerdict].self, forKey: .verdicts)
    self.requestReviewers = try c.decode(Bool.self, forKey: .requestReviewers)
    self.updateMethods = try c.decodeIfPresent([PullRequestUpdateMethod].self, forKey: .updateMethods)
    self.labels = try c.decodeIfPresent(Bool.self, forKey: .labels)
  }

  public func encode(to encoder: any Encoder) throws {
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encodeIfPresent(stackRebase, forKey: .stackRebase)
    try c.encode(actions, forKey: .actions)
    try c.encode(comment, forKey: .comment)
    try c.encode(resolve, forKey: .resolve)
    try c.encode(verdicts, forKey: .verdicts)
    try c.encode(requestReviewers, forKey: .requestReviewers)
    try c.encodeIfPresent(updateMethods, forKey: .updateMethods)
    try c.encodeIfPresent(labels, forKey: .labels)
  }
}
